def val_from_lengths(lengths):
    # f(n)=number of lengths L with n<L
    f=[0]*301
    for L in lengths:
        for n in range(L): f[n]+=1
    dp=[INF]*6001; dp[0]=0; maxs=0
    for _ in range(20):
        ndp=[INF]*6001
        # group by costs intervals: f nonincr, but direct ok for a few tests
        for s in range(maxs+1):
            b=dp[s]
            if b>=INF: continue
            for n,c in enumerate(f):
                v=b+c
                if v<ndp[s+n]: ndp[s+n]=v
        dp=ndp; maxs+=300
    return sum(dp), dp

for lens in ([300],[200,100],[150,150],[100,100,100],[250,50],[100,80,60,40,20],[1]*300):
