import random, time
INF=10**9

def val(lens):
    lens=sorted([x for x in lens if x>0])
    m=len(lens)
    A=[0]+lens
    dp=[0]
    for _ in range(20):
        ndp=[INF]*(len(dp)+m)
        for a,da in enumerate(dp):
            if da>=INF: continue
            for r in range(m+1):
                c=da+A[r]
                if c<ndp[a+r]: ndp[a+r]=c
        dp=ndp
    return sum(dp[1:]), dp

def norm(parts): return tuple(sorted(p for p in parts if p>0))

def show(p):
    v,_=val(p); print('test val',v,'m',len(p),'sum',sum(p),'parts',p[:40])

for p in ([300],[100,200],[150,150],[100,100,100],[20,40,60,80,100],[10,20,30,40,50,60,90],[1]*300,[5]*60,[10]*30, list(range(1,25))):
    if sum(p)==300: show(list(p))

best=(0,())
# structured: powers/arithmetic rounded from x_i proportional i^alpha
for m in range(1,101):
  for alpha in [0,0.25,0.5,0.75,1,1.25,1.5,2,3]:
    weights=[(i+1)**alpha for i in range(m)]
    tot=sum(weights)
    p=[max(1,int(round(300*w/tot))) for w in weights]
    # adjust to sum 300
    while sum(p)>300:
      j=max(range(m), key=lambda i:p[i])
      if p[j]>1: p[j]-=1
      else: break
    while sum(p)<300:
      j=max(range(m), key=lambda i:weights[i]-p[i]*tot/300)
      p[j]+=1
    p=norm(p); v,_=val(p)
    if v>best[0]: best=(v,p); print('struct best',best)

# random compositions
start=time.time()
for m in range(1,121):
  for _ in range(100):
    cuts=sorted(random.sample(range(1,300), m-1)) if m>1 else []
    p=[cuts[0]]+[cuts[i]-cuts[i-1] for i in range(1,len(cuts))]+([300-cuts[-1]] if cuts else [300])
    p=norm(p); v,_=val(p)
    if v>best[0]: best=(v,p); print('rand best',best)
print('random done',best,'time',time.time()-start)

# greedy local improve
seeds=[best[1], norm([20,40,60,80,100]), norm([10,20,30,40,50,60,90]), norm(list(range(1,25)))]
for seed in seeds:
    cur=list(seed); curv=val(cur)[0]
    print('seed',curv,len(cur),tuple(cur))
    while True:
        bv=curv; bp=None; n=len(cur)
        # unit transfer/split/merge limited
        for i in range(n):
            if cur[i]>1:
                for j in range(n):
                    if i==j: continue
                    q=cur[:]; q[i]-=1; q[j]+=1; q=list(norm(q))
                    vv=val(q)[0]
                    if vv>bv: bv=vv; bp=q
                q=cur[:]; q[i]-=1; q.append(1); q=list(norm(q))
                vv=val(q)[0]
                if vv>bv: bv=vv; bp=q
        for i in range(n):
          for j in range(i+1,n):
            q=[cur[k] for k in range(n) if k!=i and k!=j]+[cur[i]+cur[j]]; q=list(norm(q))
            vv=val(q)[0]
            if vv>bv: bv=vv; bp=q
        if bp is None: break
        cur=bp; curv=bv
        if curv>best[0]: best=(curv,tuple(cur)); print('local best',best)
    print('local opt',curv,len(cur),tuple(cur))
print('FINAL',best)
